{
 "research_concepts": [
  "player roles",
  "offensive shapers",
  "cuts (basketball)",
  "drives (basketball)",
  "role portability",
  "player performance consistency",
  "team context change"
 ],
 "methodological_questions": [
  "player classification by offensive style",
  "quantifying player impact across different teams",
  "controlling for confounding factors in player mobility studies",
  "defining 'travel better' for player roles",
  "sample size for player role studies"
 ],
 "historical_evidence": [
  {
   "id": "FAM:SF-CHT-057",
   "status_as_recorded": "supported",
   "finding": "Pre-move cut share (vs drive share) predicts whether a connector's organizational function reproduces after a move. Cut share rho=+0.265 p=0.011 AUC 0.653. Cut-drive rho=+0.314 p=0.002 AUC 0.656. Drive rho=-0.278 p=0.007. Top cut tercile 65% portable median Delta +0.167; bottom 35% median -0.039."
  },
  {
   "id": "FAM:SF-APPM-014",
   "status_as_recorded": "not a hypothesis test",
   "finding": "Audit overall FAIL: OTHER 20.2% vs <10% target; 40.8% low confidence; DRIVE foul-draw 1.7% vs 14-22% benchmark; most PTs PPP above benchmark band; MIA identity checks fail. 'play type labels have systematic issues that undermine adaptation findings'; foul possessions leak into OTHER."
  },
  {
   "id": "FAM:SF-APPS-011",
   "status_as_recorded": "supported",
   "finding": "DRIVE PPP is materially higher in RS than playoffs, so an RS-calibrated optimizer over-recommends DRIVE. DRIVE RS 1.198 vs PO 0.912 (-0.286, 25 teams); PNR -0.173; PULL_UP +0.301; others within -0.07."
  },
  {
   "id": "FAM:SF-CHT-029",
   "status_as_recorded": "artifact",
   "finding": "FAIL decay-sanity: DRIVE lifts +0.015,+0.020,+0.018,+0.021,+0.020 (flat). Within-team: DRIVE lag-1 +0.015 to -0.002. Cohen d ~0.01-0.03; p~0 from n>150k. Callable play-type horizons = 0."
  },
  {
   "id": "FAM:SF-CHT-087",
   "status_as_recorded": "artifact",
   "finding": "Organizer-connector gap CI includes 0 after correcting a menu-similarity confound; KW p=0.047 is population-level, pairwise is suggestive."
  },
  {
   "id": "FAM:SF-APPS-088",
   "status_as_recorded": "supported",
   "finding": "Connector absence displaces team offensive identity (D_A) more than usage-matched non-organizer absence. Usage-matched conn vs role D_A 0.2020 vs 0.1021, t=5.97 p=2.87e-08. Usage-matched vs role: paired dD_A +0.1151, P(conn>ctrl)=81.2%, t=6.35 p=7.35e-09 n=96. Vs terminal: +0.0777 t=2.37 p=0.0261 n=25."
  },
  {
   "id": "FAM:SF-CHT-052",
   "status_as_recorded": "inconclusive",
   "finding": "mean sim ABSORBED +0.863 vs CASCADE +0.848; Spearman(sim, -gap)=-0.19 (wrong-signed). Embiid 23-24 cascades with Reed sim 0.94. Similarity does not separate absorption from cascade; almost always findable."
  },
  {
   "id": "FAM:SF-APPS-025",
   "status_as_recorded": "untestable",
   "finding": "Caliper 0.10: A excess +0.076 [+0.068,+0.084] n=3421 p=0; B excess +0.014 [-0.019,+0.046] n=255 p=0.386. Gap B-A = -0.062. Caliper sweep B CIs include 0 except 0.15. Group B caliper-0.10 CI includes 0 (p=0.386, n=255 clusters=242); Group B is a reconstructed post-hoc cohort, not a validated successful-adaptation sample."
  },
  {
   "id": "FAM:SF-PAP-009",
   "status_as_recorded": "supported",
   "finding": "G1 72 team-seasons with >=200 poss in both; G2 |rho(COVERED,TALENT)|=0.042, aux R2=0.203; G3 rho(TALENT,PPP)=+0.027. Lineup coverage (>=1 organizer, shaper, terminal) varies within team, is separable from talent/counts, and talent control behaves."
  }
 ],
 "failed_approaches": [
  {
   "id": "FAM:SF-APPM-014",
   "what_failed": "Inferred play-type labels for audit against benchmarks",
   "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw); label_or_classification_error; leakage; small_sample"
  },
  {
   "id": "FAM:SF-CHT-029",
   "what_failed": "Measuring persistent impact score for play-type actions (lag-1 effect >= lag-2)",
   "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw); confounding"
  },
  {
   "id": "FAM:SF-CHT-087",
   "what_failed": "Assessing portability median Delta robustness to pairing rule among movers",
   "why": "C_artifact (apparent effect produced by a construction, selection or labelling flaw); confounding; small_sample"
  },
  {
   "id": "FAM:SF-CHT-052",
   "what_failed": "Using similar-profile teammates to separate absorption from cascade when a player sits",
   "why": "B_powered_null (adequately powered null result); label_or_classification_error"
  },
  {
   "id": "FAM:SF-APPS-025",
   "what_failed": "Comparing overall-offense excess for teams that adapt vs continue a suppressed play type",
   "why": "A_unanswerable (question not answerable with the data or design); PLACEBO_DEPENDENCE; SAMPLE_SIZE_POWER"
  }
 ],
 "evidence_establishes": [
  "A previous study (FAM:SF-CHT-057) directly found that pre-move cut share predicts connector portability, and drive share negatively predicts it, supporting the hypothesis that cut-heavy roles travel better (for connectors).",
  "Play-type labels, including 'DRIVE', have systematic issues (FAM:SF-APPM-014), such as high 'OTHER' percentage, low confidence, and incorrect foul-draw rates, which undermine adaptation findings. This suggests that classification of 'cut-heavy' and 'drive-heavy' shapers based on current play-type labels is problematic.",
  "DRIVE play type performance (PPP) is significantly lower in the playoffs compared to the regular season (FAM:SF-APPS-011), indicating that role effectiveness can vary by game context.",
  "Measuring the persistent impact of play types like 'DRIVE' is confounded by team quality, leading to artifactual flat effects (FAM:SF-CHT-029).",
  "Defining and measuring 'portability' for movers is complex and can be affected by confounds like 'menu-similarity' and small sample sizes (FAM:SF-CHT-087).",
  "Connector absence significantly displaces team offensive identity more than non-organizer absence (FAM:SF-APPS-088), suggesting that certain roles have a measurable impact on team identity.",
  "Lineup coverage (existence of organizers, shapers, terminals) varies and is separable from talent (FAM:SF-PAP-009), indicating that these structural roles are distinct concepts."
 ],
 "evidence_does_not_establish": [
  "Whether the specific 'shaper' role, as opposed to 'connector' (studied in FAM:SF-CHT-057), exhibits the same portability patterns based on cut/drive heaviness.",
  "The reliability of classifying players as 'cut-heavy shapers' or 'drive-heavy shapers' given the known issues with play-type label accuracy (FAM:SF-APPM-014).",
  "How to reliably measure the 'travel better' aspect for shapers in a way that is robust to confounding factors and label errors.",
  "The optimal methodology for controlling for team quality and other confounding factors when assessing player role portability."
 ],
 "own_inferences": [
  "The research question is very similar to FAM:SF-CHT-057, which found supportive evidence for connectors. It is plausible that shapers might exhibit similar patterns, but this would require explicit testing.",
  "The identified issues with play-type labels (FAM:SF-APPM-014) are a significant obstacle to accurately identifying and comparing 'cut-heavy' vs 'drive-heavy' shapers.",
  "The concept of 'travel better' needs a precise operational definition, likely involving a measure of performance change or consistency after a player moves to a new team."
 ],
 "uncertainties": [
  "The precise definition of 'shapers' in relation to 'connectors' and 'organizers' used in previous studies.",
  "The extent to which the 'play type label accuracy' issues (FAM:SF-APPM-014) have been mitigated or are still prevalent in the current data pipeline for the specified seasons.",
  "The specific measure of 'travel better' intended by the research question (e.g., impact on new team's offense, individual efficiency, role consistency)."
 ],
 "historical_effect": {
  "changed_decision": "yes",
  "explanation": "The historical evidence significantly changed the decision. While FAM:SF-CHT-057 directly supports a similar hypothesis for 'connectors' and suggests the question is answerable in principle, FAM:SF-APPM-014 reveals critical, systematic issues with play-type labels (including DRIVE) that 'undermine adaptation findings'. This makes the core classification ('cut-heavy' vs 'drive-heavy') and subsequent analysis highly unreliable. The decision shifted from potentially proceeding to not proceeding without addressing the label quality first."
 },
 "testability": {
  "p_testable": 0.2,
  "blocking_constraints": [
   {
    "code": "LABEL_ERROR",
    "text": "The play-type labels, specifically for 'DRIVE' and overall, have known systematic issues (FAM:SF-APPM-014) that undermine adaptation findings and classification of players as 'cut-heavy' or 'drive-heavy'. This makes the independent variable (player type) and dependent variable (performance/portability) unreliable."
   },
   {
    "code": "SAMPLE_SIZE_POWER",
    "text": "Although FAM:SF-CHT-057 found results with n=92 connector movers, the current data offers n=24 units. If 'units' refers to player-seasons or player movements, this is a very small sample size for distinguishing between player archetypes and measuring portability, especially given the need for player movement events."
   },
   {
    "code": "CONFOUNDING",
    "text": "Previous studies (FAM:SF-CHT-029, FAM:SF-CHT-087) highlight confounding issues (e.g., team quality, menu-similarity) when assessing play-type impact and player portability, which would need careful control and could be difficult to disentangle with unreliable labels."
   }
  ]
 },
 "prior_work": {
  "already_answered": "partly",
  "cited": [
   "FAM:SF-CHT-057"
  ],
  "summary": "FAM:SF-CHT-057 directly supported a similar hypothesis, finding that pre-move cut share predicts whether a 'connector's' organizational function reproduces after a move, while drive share negatively predicts it. This provides strong prior evidence for the general concept of cut/drive-based role portability. However, this was for 'connectors,' not explicitly 'shapers' as posed in the current question, and did not address the known label quality issues."
 },
 "risks": [
  {
   "code": "LABEL_ERROR",
   "text": "The primary risk is the known systematic issues with play-type labels (FAM:SF-APPM-014), particularly for 'DRIVE' and overall low confidence/high 'OTHER' rates. This directly impacts the ability to accurately classify players as 'cut-heavy' or 'drive-heavy shapers' and to reliably measure their performance and portability."
  },
  {
   "code": "SAMPLE_SIZE_POWER",
   "text": "The available data lists 'n=24 units'. If these units refer to player movements or shapers, this is likely an insufficient sample size to achieve useful statistical power for distinguishing between two player archetypes and assessing their portability across different team contexts, especially when controlling for confounders. FAM:SF-CHT-057 used n=92 connector movers, and still listed small_sample as a limitation."
  },
  {
   "code": "CONFOUNDING",
   "text": "Player portability is highly susceptible to confounding factors such as new team quality, coaching changes, teammate quality, and role changes in the new environment. Previous work (FAM:SF-CHT-029, FAM:SF-CHT-087) has highlighted team-quality and 'menu-similarity' as confounders for play-type impact and portability."
  },
  {
   "code": "OUTCOME_DERIVED_LABEL",
   "text": "Defining 'travel better' requires a robust and unbiased measure of performance consistency or impact in a new team context. This measure itself could be influenced by the same underlying factors that affect the player's role, potentially leading to circularity or bias."
  },
  {
   "code": "DRIFT_NONSTATIONARITY",
   "text": "The difference in DRIVE PPP between regular season and playoffs (FAM:SF-APPS-011) indicates that play-type effectiveness can vary by context. If 'travel better' involves performance across different seasons or contexts (e.g., regular season vs. playoffs), this non-stationarity needs to be accounted for."
  }
 ],
 "predicted_outcome": {
  "supported": 0.05,
  "rejected": 0.05,
  "untestable": 0.8,
  "artifact": 0.05,
  "uncertain": 0.05
 },
 "decision": "do_not_proceed",
 "design": {
  "estimand": "The difference in change of offensive impact or role consistency (portability) for 'cut-heavy shapers' compared to 'drive-heavy shapers' following a team change (player movement or significant team roster/coaching alteration). Portability would be measured as the correlation between pre-move and post-move offensive production or role usage, adjusted for team context.",
  "unit": "Player-season pairs (pre-move, post-move) for players identified as 'shapers' who changed teams or experienced a significant team context change. A 'shaper' is defined as a player whose primary offensive responsibility involves initiating or significantly contributing to a high volume of cuts or drives, as classified by play-type data.",
  "sample": "NBA players from 2022-23 to 2025-26 seasons who are classified as 'shapers' and have experienced a team change. Given 'n=24 units', this sample is too small. A minimum of 100-200 such player movements would be required for sufficient power, similar to or exceeding FAM:SF-CHT-057 (n=92).",
  "power": "Not estimable with the current data (n=24 units). For a meaningful test, power calculations would require a larger sample of player movements and an estimate of the expected effect size and variability. FAM:SF-CHT-057, with n=92, still noted 'small_sample' as a limitation.",
  "controls": "Control for player talent (e.g., by previous season's advanced metrics), new team's offensive scheme and personnel, coaching changes, and specific role assigned on the new team. A matched-pair design or regression analysis with fixed effects for player and team could be considered. Confounders like 'menu-similarity' (FAM:SF-CHT-087) and team quality (FAM:SF-CHT-029) must be addressed.",
  "falsification": "A strong falsification would involve demonstrating that the play-type labels used for classification and measurement are accurate and reliable (e.g., by passing the audit checks that FAM:SF-APPM-014 failed) before any analysis of portability. If the labels are unreliable, any observed effect would be an artifact.",
  "multiplicity": "If multiple measures of 'portability' or different definitions of 'shapers' are explored, adjust p-values for multiple comparisons (e.g., Bonferroni correction, False Discovery Rate).",
  "decision_rule": "Reject the null hypothesis (no difference in portability) if the effect size for cut-heavy shapers is significantly greater than drive-heavy shapers (e.g., p < 0.05) and the effect is robust across different control specifications and sensitivity analyses. However, this is predicated on resolving the label quality and sample size issues.",
  "data_version": "NBA 2022-23 to 2025-26 (complete as of 2026-06-21). Prior to any analysis, a full audit of play-type label accuracy, similar to FAM:SF-APPM-014, must be conducted on this data, and issues resolved."
 }
}

